import 'package:flutter_test/flutter_test.dart';
import 'package:mobile/integration/signals.dart';

// Expected values generated by backend/app/chain/signals.py, which matches @semaphore-protocol/core and the
// Rust engine inside the Semaphore Flutter SDK.
void main() {
  test('message text matches backend message_text (UTF-8, exact bytes)', () {
    const payload = '{"category":"Bullying","title":"Café ☕"}';
    expect(messageText(payload), 'm:ee1d554287ba38532d42ded600fd');
    expect(
      bytes32Text(messageText(payload)).toString(),
      '49405277429870347260340231260311980093011532936086390959942129519129425870848',
    );
  });

  test('scope text encoding matches backend bytes32_text', () {
    expect(
      bytes32Text('cmp:2026-10-10').toString(),
      '44972332904357404903854500619547100365169977065645179200296560551232110854144',
    );
    expect(() => bytes32Text('x' * 32), throwsArgumentError);
  });

  test('commitment <-> 32-byte little-endian element round trip', () {
    const c =
        '4794474613829683445382895362262407640958131911260737082524399359773393694730';
    final e = commitmentToElement(c);
    expect(
      e.map((b) => b.toRadixString(16).padLeft(2, '0')).join(),
      '0a30a6e7449bf5b75945a2492d8e559a9233d99ae2d132d4c2fff1449393990a',
    );
    expect(elementToDecimal(e), c);
  });
}
